TEST_as:
SELECT *
FROM tblClients AS C, tblFactures AS F
WHERE C.idCLient = F.fiClient;

TEST_like:
SELECT *
FROM tblClients
WHERE fldNom LIKE '?e*';

TEST_like_and_same_line:
SELECT *
FROM tblClients
WHERE fldNom LIKE '?e*' AND fldLocalité = 'Luxembourg';

TEST_order_by:
SELECT fldNom, fldPrénom
FROM tblClients
ORDER BY fldNom DESC, fldPrénom;

TEST_order_by_asc_default:
SELECT fldNom, fldPrénom
FROM tblClients
ORDER BY fldNom;
